package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    processed := 0

    for id := 1; id <= 3; id++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for i := 0; i < 1000; i++ {
                processed = processed + 1
            }
        }()
    }

    wg.Wait()
    fmt.Println("обработано:", processed)
}

// Дело: Go — конкурентность
// Эпизод: итоговое дело

package main

import (
    "fmt"
    "sync"
    "time"
)

func worker(id int) {
    for {
        fmt.Println("обработчик", id, "работает")
        time.Sleep(30 * time.Millisecond)
    }
}

func main() {
    var wg sync.WaitGroup

    for id := 1; id <= 3; id++ {
        wg.Add(1)
        go worker(id)
    }

    fmt.Println("сервис остановлен")
}
